// backend/Money.js is js/money.js made into plain Apps Script (generated by
// npm run stamp), and Apps Script loads every backend file into one scope.
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.join(__dirname, "..");
const read = (f) => fs.readFileSync(path.join(ROOT, f), "utf8");
const gen = () => import("../scripts/make-backend-money.mjs");

test("backend/Money.js is current", async () => {
  const { generate } = await gen();
  assert.equal(read("backend/Money.js"), generate(read("js/money.js")), "run npm run stamp");
});

test("backend/Money.js starts with the generated-file line and has no export left", async () => {
  const src = read("backend/Money.js");
  assert.equal(src.split("\n")[0], "// Generated from js/money.js by npm run stamp. Do not edit.");
  assert.equal(/^\s*(export|import)\b/m.test(src), false);
});

test("the generator refuses what stripping export would not make valid", async () => {
  const { generate } = await gen();
  assert.match(generate("export function a() {}\nexport const b = 1;\n"), /^\/\/ Generated[^\n]*\nfunction a\(\) \{\}\nconst b = 1;\n$/);
  for (const bad of [
    'import { x } from "./x.js";\nexport function a() {}\n',
    "export default function a() {}\n",
    "function a() {}\nexport { a };\n",
    "export * from './x.js';\n",
    "  export function a() {}\n",
    "const m = await import('./x.js');\n",
  ]) {
    assert.throws(() => generate(bad), /js\/money\.js/, JSON.stringify(bad));
  }
});

// The top-level names a file declares: function, async function, generator,
// class, var, let and const (each name of a comma list too).
function topNames(src) {
  const out = [];
  for (const m of src.matchAll(/^(?:async\s+)?(?:function\s*\*?|class)\s*([A-Za-z0-9_$]+)/gm)) out.push(m[1]);
  for (const m of src.matchAll(/^(?:var|let|const)\s+([^;]*)/gm)) {
    // var a = 1, b = 2 -> a, b (a comma inside brackets or a string is not a new name)
    let depth = 0;
    let quote = null;
    let part = "";
    const parts = [];
    for (const ch of m[1]) {
      if (quote) {
        if (ch === quote) quote = null;
      } else if (ch === '"' || ch === "'" || ch === "`") quote = ch;
      else if ("([{".includes(ch)) depth++;
      else if (")]}".includes(ch)) depth--;
      else if (ch === "," && depth === 0) {
        parts.push(part);
        part = "";
        continue;
      }
      part += ch;
    }
    parts.push(part);
    for (const p of parts) {
      const name = p.trim().match(/^([A-Za-z0-9_$]+)/);
      assert.ok(name, "a top-level declaration this test can’t read: " + m[0].slice(0, 60));
      out.push(name[1]);
    }
  }
  return out;
}

test("the name reader finds every kind of top-level declaration", () => {
  const src = "function a() {}\nasync function b() {}\nfunction* c() {}\nclass D {}\nvar e = 1, f = [1, 2], g = { h: 1, i: 2 };\nlet j;\nconst k = f(1, 2);\n  function nested() {}\n";
  assert.deepEqual(topNames(src).sort(), ["D", "a", "b", "c", "e", "f", "g", "j", "k"]);
});

test("no name is declared at the top of two backend files", () => {
  // Apps Script puts every file in one scope: a second `function x` silently
  // replaces the first, and a second const or let stops the whole web app.
  const seen = new Map();
  const files = fs.readdirSync(path.join(ROOT, "backend")).filter((n) => n.endsWith(".js"));
  assert.ok(files.includes("Money.js") && files.includes("Mcp.js"), "Money.js and Mcp.js are checked too");
  for (const f of files) {
    for (const name of new Set(topNames(read("backend/" + f)))) {
      assert.equal(seen.has(name), false, name + " is in both " + seen.get(name) + " and " + f);
      seen.set(name, f);
    }
  }
});

test("no file reads another file's names at load time", () => {
  // Apps Script runs the files alphabetically; a top-level expression may only
  // use what its own file defines. Each file is run alone with just the
  // Google services stubbed, and must not throw.
  const vm = require("node:vm");
  for (const f of fs.readdirSync(path.join(ROOT, "backend")).filter((n) => n.endsWith(".js"))) {
    assert.doesNotThrow(() => vm.runInContext(read("backend/" + f), vm.createContext({})), f);
  }
});
